import { SECOND } from '@proton/shared/lib/constants';

import Metrics from './Metrics';
import { METRICS_BATCH_SIZE, METRICS_REQUEST_FREQUENCY_SECONDS } from './constants';
import MetricsApi from './lib/MetricsApi';
import MetricsRequestService from './lib/MetricsRequestService';

export * from './lib/observeApiError';
export { default as observeApiError } from './lib/observeApiError';

const metricsApi = new MetricsApi();
const metricsRequestService = new MetricsRequestService(metricsApi, {
    reportMetrics: true,
    batch: {
        frequency: METRICS_REQUEST_FREQUENCY_SECONDS * SECOND,
        size: METRICS_BATCH_SIZE,
    },
});
const metrics = new Metrics(metricsRequestService);

export default metrics;
{
    "name": "@proton/metrics",
    "description": "Metrics library",
    "scripts": {
        "check-types": "tsc",
        "generate-metrics": "ts-node -P scripts/tsconfig.metrics-scripts.json ./scripts/generate-metrics.ts",
        "generate-schema-types": "json2ts -i 'json-schema-registry/observability/client/web*.schema.json' -o types/ --no-additionalProperties && json2ts -i 'json-schema-registry/observability/client/drive*.schema.json' -o types/ --no-additionalProperties && json2ts -i 'json-schema-registry/observability/client/docs*.schema.json' -o types/ --no-additionalProperties",
        "lint": "eslint . --ext ts --quiet --cache",
        "test": "jest",
        "test:ci": "jest --coverage --runInBand --ci",
        "test:watch": "jest --watch",
        "update-metrics": "rimraf json-schema-registry types && git clone $SCHEMA_REPOSITORY && yarn generate-schema-types && yarn generate-metrics"
